package cn.xinji.agentplatform.adjudication.materials;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static cn.xinji.agentplatform.adjudication.materials.MaterialCandidateDecisions.*;
import static cn.xinji.agentplatform.adjudication.materials.MaterialOrganizationModel.*;
import static cn.xinji.agentplatform.adjudication.casework.AdjudicationCaseWork.sha256;
import cn.xinji.agentplatform.adjudication.casework.CaseWorkContract.*;

class MaterialCandidateDecisionsTest {
    final String runId="11111111-1111-4111-8111-111111111111",versionId="22222222-2222-4222-8222-222222222222";
    final Instant created=Instant.parse("2026-10-03T00:00:00Z"),now=created.plusSeconds(3600),expiry=created.plus(Duration.ofDays(30));
    final String raw="😀申请方称使用弹簧。";
    final Input input=new Input("s1",MaterialOrganizationModel.Side.APPLICANT,new Source("A","v1","page:1",sha256(raw),InputKind.PROJECT_AUTHORED),raw);
    final Candidate candidate=new MaterialCandidateValidator().validate(List.of(input),"{\"candidates\":[{\"kind\":\"PARTY_ASSERTION\",\"sourceTag\":\"s1\",\"side\":\"APPLICANT\",\"statement\":\"申请方称使用弹簧\",\"exactQuote\":\"申请方称使用弹簧\"}]}").getFirst();
    final MaterialCandidateDecisions service=new MaterialCandidateDecisions(new Limits(2000,2000));
    Run run(){return new Run(runId,"case-1",3,created,expiry);}
    Current current(){return new Current("case-1",4,0,3,now,Map.of());}
    Request request(Action a){return new Request(4,0,a,a==Action.EDIT?"人工限定为申请方陈述":null,a==Action.ACCEPT?null:"逐字核对后的处理理由");}
    Decision decide(Action a){return service.decide(run(),candidate,input,current(),request(a),"trusted-operator",versionId);}
    void invalid(String code,Runnable work){assertEquals(code,assertThrows(IllegalArgumentException.class,work::run).getMessage());}

    @Test void acceptPreservesCandidateAndBoundOriginal(){var d=decide(Action.ACCEPT);assertEquals(candidate.statement(),d.machineStatement());assertEquals(candidate.statement(),d.humanText());assertEquals(input.source(),d.source());assertEquals(2,d.start());assertEquals(raw.substring(d.start(),d.end()),d.exactQuote());assertEquals(5,d.workVersion());assertEquals(1,d.organizationVersion());assertEquals(3,d.inputVersion());assertEquals(Semantic.HUMAN_REVIEWED_MATERIAL_STATEMENT,d.semantic());assertEquals(Scope.SELECTED_MATERIALS,d.scope());assertEquals(expiry,d.expiresAt());assertNull(d.baseVersionId());}
    @Test void editDoesNotOverwriteMachineOrQuote(){var d=decide(Action.EDIT);assertEquals(request(Action.EDIT).humanText(),d.humanText());assertEquals(candidate.statement(),d.machineStatement());assertEquals(candidate.exactQuote(),d.exactQuote());assertEquals(candidate.providerSide(),d.providerSide());assertNotEquals(d.humanText(),candidate.statement());}
    @Test void rejectHasReasonButNoAdoptedStatement(){var d=decide(Action.REJECT);assertEquals(Semantic.REJECTED_CANDIDATE,d.semantic());assertNull(d.humanText());assertEquals(request(Action.REJECT).reason(),d.reason());assertEquals(candidate.statement(),d.machineStatement());}
    @ParameterizedTest @EnumSource(Kind.class) void everyCategoryRemainsSelectedMaterialsNotConfirmedFact(Kind kind){var c=new Candidate("c1",kind,candidate.providerSide(),candidate.statement(),candidate.exactQuote(),candidate.start(),candidate.end(),candidate.sourceId(),candidate.sourceVersion(),candidate.sourceSha256(),candidate.originalLocator(),candidate.sourceTag());var d=service.decide(run(),c,input,current(),request(Action.ACCEPT),"operator",versionId);assertEquals(kind,d.kind());assertEquals(Scope.SELECTED_MATERIALS,d.scope());assertEquals(Semantic.HUMAN_REVIEWED_MATERIAL_STATEMENT,d.semantic());assertThrows(IllegalArgumentException.class,()->Semantic.valueOf("CONFIRMED_FACT"));}
    @Test void versionAndOrganizationCasAreIndependent(){invalid("MATERIAL_DECISION_VERSION_CONFLICT",()->service.decide(run(),candidate,input,current(),new Request(3,0,Action.ACCEPT,null,null),"operator",versionId));invalid("MATERIAL_DECISION_VERSION_CONFLICT",()->service.decide(run(),candidate,input,current(),new Request(4,1,Action.ACCEPT,null,null),"operator",versionId));}
    @Test void invalidVersionsRejected(){invalid("MATERIAL_DECISION_VERSION_INVALID",()->service.decide(run(),candidate,input,current(),new Request(0,0,Action.ACCEPT,null,null),"operator",versionId));invalid("MATERIAL_DECISION_VERSION_INVALID",()->service.decide(run(),candidate,input,current(),new Request(4,-1,Action.ACCEPT,null,null),"operator",versionId));}
    @Test void staleInputNeverAdopted(){var c=new Current("case-1",5,0,4,now,Map.of());invalid("MATERIAL_MODEL_RUN_STALE",()->service.decide(run(),candidate,input,c,new Request(5,0,Action.ACCEPT,null,null),"operator",versionId));}
    @Test void crossCaseRejected(){var c=new Current("other-case",4,0,3,now,Map.of());invalid("MATERIAL_DECISION_CASE_CONFLICT",()->service.decide(run(),candidate,input,c,request(Action.ACCEPT),"operator",versionId));}
    @Test void sourceVersionAndBytesCannotDrift(){var s=input.source();var drift=new Input("s1",input.side(),new Source(s.id(),"v2",s.locator(),s.sha256(),s.kind()),raw);invalid("MATERIAL_DECISION_SOURCE_DRIFTED",()->service.decide(run(),candidate,drift,current(),request(Action.ACCEPT),"operator",versionId));var bytes=new Input("s1",input.side(),s,raw+"变化");invalid("MATERIAL_DECISION_SOURCE_DRIFTED",()->service.decide(run(),candidate,bytes,current(),request(Action.ACCEPT),"operator",versionId));}
    @Test void sideLocatorAndTagCannotDrift(){for(Input i:List.of(new Input("s1",MaterialOrganizationModel.Side.RESPONDENT,input.source(),raw),new Input("s2",input.side(),input.source(),raw),new Input("s1",input.side(),new Source("A","v1","page:2",sha256(raw),InputKind.PROJECT_AUTHORED),raw))){invalid("MATERIAL_DECISION_SOURCE_DRIFTED",()->service.decide(run(),candidate,i,current(),request(Action.ACCEPT),"operator",versionId));}}
    @Test void quoteOffsetDriftRejected(){var c=new Candidate("c1",candidate.kind(),candidate.providerSide(),candidate.statement(),candidate.exactQuote(),3,candidate.end(),candidate.sourceId(),candidate.sourceVersion(),candidate.sourceSha256(),candidate.originalLocator(),candidate.sourceTag());invalid("MATERIAL_DECISION_QUOTE_DRIFTED",()->service.decide(run(),c,input,current(),request(Action.ACCEPT),"operator",versionId));}
    @Test void expiryIsClosedAtExactDeadline(){var c=new Current("case-1",4,0,3,expiry,Map.of());assertEquals("MATERIAL_DECISION_EXPIRED",assertThrows(SecurityException.class,()->service.decide(run(),candidate,input,c,request(Action.ACCEPT),"operator",versionId)).getMessage());}
    @Test void rollbackClockRejected(){var c=new Current("case-1",4,0,3,created.minusSeconds(1),Map.of());assertThrows(SecurityException.class,()->service.decide(run(),candidate,input,c,request(Action.ACCEPT),"operator",versionId));}
    @Test void cannotExtendParentRetention(){var r=new Run(runId,"case-1",3,created,expiry.plusSeconds(1));invalid("MATERIAL_DECISION_RETENTION_INVALID",()->service.decide(r,candidate,input,current(),request(Action.ACCEPT),"operator",versionId));assertEquals(expiry,decide(Action.EDIT).expiresAt());}
    @Test void acceptAndRejectCannotSmuggleHumanReplacement(){for(Action a:List.of(Action.ACCEPT,Action.REJECT)){invalid("MATERIAL_DECISION_HUMAN_TEXT_NOT_ALLOWED",()->service.decide(run(),candidate,input,current(),new Request(4,0,a,"隐藏覆盖","理由"),"operator",versionId));}}
    @Test void explicitEditAndRejectionRequireReasons(){invalid("MATERIAL_DECISION_REASON_REQUIRED",()->service.decide(run(),candidate,input,current(),new Request(4,0,Action.EDIT,"改文",null),"operator",versionId));invalid("MATERIAL_DECISION_REASON_REQUIRED",()->service.decide(run(),candidate,input,current(),new Request(4,0,Action.REJECT,null," "),"operator",versionId));invalid("MATERIAL_HUMAN_TEXT_REQUIRED",()->service.decide(run(),candidate,input,current(),new Request(4,0,Action.EDIT," ","理由"),"operator",versionId));}
    @Test void noDefaultDecisionOrActor(){invalid("MATERIAL_DECISION_REQUIRED",()->service.decide(run(),candidate,input,current(),new Request(4,0,null,null,null),"operator",versionId));invalid("MATERIAL_DECISION_ACTOR_INVALID",()->service.decide(run(),candidate,input,current(),request(Action.ACCEPT)," ",versionId));}
    @Test void duplicateDecisionBlockedWithoutChangingContext(){var map=new HashMap<String,String>();map.put(runId+":c1",versionId);var c=new Current("case-1",5,1,3,now,map);map.clear();invalid("MATERIAL_CANDIDATE_ALREADY_DECIDED",()->service.decide(run(),candidate,input,c,new Request(5,1,Action.ACCEPT,null,null),"operator",UUID.randomUUID().toString()));assertEquals(1,c.decidedCandidates().size());}
    @Test void revisionPreservesPriorVersionAndNeverExtendsExpiry(){var prior=decide(Action.ACCEPT);var c=new Current("case-1",6,2,3,now.plusSeconds(10),Map.of(runId+":c1",versionId));String next=UUID.randomUUID().toString();var d=service.revise(prior,run(),input,c,new Request(6,2,Action.EDIT," 第二次人工正文 ","更正理由"),"second-operator",next);assertEquals(versionId,d.baseVersionId());assertEquals(3,d.organizationVersion());assertEquals(7,d.workVersion());assertEquals(candidate.statement(),prior.humanText());assertEquals(" 第二次人工正文 ",d.humanText());assertEquals(prior.machineStatement(),d.machineStatement());assertEquals(prior.expiresAt(),d.expiresAt());}
    @Test void noncurrentBaseAndVersionReuseRejected(){var prior=decide(Action.ACCEPT);var c=new Current("case-1",5,1,3,now,Map.of(runId+":c1",UUID.randomUUID().toString()));invalid("MATERIAL_DECISION_BASE_VERSION_CONFLICT",()->service.revise(prior,run(),input,c,new Request(5,1,Action.EDIT,"改文","理由"),"operator",UUID.randomUUID().toString()));var head=new Current("case-1",5,1,3,now,Map.of(runId+":c1",versionId));invalid("MATERIAL_DECISION_VERSION_REUSE",()->service.revise(prior,run(),input,head,new Request(5,1,Action.EDIT,"改文","理由"),"operator",versionId));}
    @Test void rejectionCannotBeRevisedIntoAcceptance(){var prior=decide(Action.REJECT);var c=new Current("case-1",5,1,3,now,Map.of(runId+":c1",versionId));invalid("MATERIAL_DECISION_REVISION_NOT_ALLOWED",()->service.revise(prior,run(),input,c,new Request(5,1,Action.EDIT,"改文","理由"),"operator",UUID.randomUUID().toString()));}
    @Test void auditReferenceCannotCarryModelOrHumanBody(){assertEquals(Set.of("versionId","runId","candidateId","organizationVersion","action"),Arrays.stream(AuditReference.class.getRecordComponents()).map(x->x.getName()).collect(java.util.stream.Collectors.toSet()));var d=decide(Action.EDIT);assertFalse(d.auditReference().toString().contains(d.humanText()));assertFalse(d.auditReference().toString().contains(d.reason()));}
    @Test void configurableLengthAndUnicodeGuards(){assertThrows(IllegalArgumentException.class,()->new Limits(0,2000));assertThrows(IllegalArgumentException.class,()->new Limits(100001,2000));var small=new MaterialCandidateDecisions(new Limits(2,2));invalid("MATERIAL_HUMAN_TEXT_REQUIRED",()->small.decide(run(),candidate,input,current(),new Request(4,0,Action.EDIT,"过长正文","理由"),"operator",versionId));invalid("MATERIAL_HUMAN_TEXT_REQUIRED",()->service.decide(run(),candidate,input,current(),new Request(4,0,Action.EDIT,"\uD800","理由"),"operator",versionId));}
    @Test void versionOverflowRejected(){var c=new Current("case-1",Long.MAX_VALUE,0,3,now,Map.of());invalid("MATERIAL_DECISION_VERSION_INVALID",()->service.decide(run(),candidate,input,c,new Request(Long.MAX_VALUE,0,Action.ACCEPT,null,null),"operator",versionId));}
    @Test void independentChildIdCannotReuseParentOrOtherDecisionKey(){invalid("MATERIAL_DECISION_VERSION_REUSE",()->service.decide(run(),candidate,input,current(),request(Action.ACCEPT),"operator",runId));String id=UUID.randomUUID().toString();var c=new Current("case-1",5,1,3,now,Map.of(runId+":c2",id));invalid("MATERIAL_DECISION_VERSION_REUSE",()->service.decide(run(),candidate,input,c,new Request(5,1,Action.ACCEPT,null,null),"operator",id));}
    @Test void acceptanceAlsoHonorsConfiguredHumanTextLimit(){var small=new MaterialCandidateDecisions(new Limits(2,2000));invalid("MATERIAL_HUMAN_TEXT_TOO_LONG",()->small.decide(run(),candidate,input,current(),request(Action.ACCEPT),"operator",versionId));}
    @Test void sourceTagMustBeExplicit(){var c=new Candidate("c1",candidate.kind(),candidate.providerSide(),candidate.statement(),candidate.exactQuote(),candidate.start(),candidate.end(),candidate.sourceId(),candidate.sourceVersion(),candidate.sourceSha256(),candidate.originalLocator(),null);invalid("MATERIAL_DECISION_SOURCE_DRIFTED",()->service.decide(run(),c,new Input(null,input.side(),input.source(),raw),current(),request(Action.ACCEPT),"operator",versionId));}

}
